// Anneaux (lon/lat) des régions, pour les rendus SVG/canvas (historique, GIF).
// Mémoïsé : aplatit Polygon/MultiPolygon en une liste d'anneaux réutilisable.
let _franceRegionRingsCache = null;
function franceRegionRings() {
  if (_franceRegionRingsCache) return _franceRegionRingsCache;
  const rings = [];
  const feats = (typeof FRANCE_REGIONS_GEOJSON !== 'undefined' && FRANCE_REGIONS_GEOJSON.features) || [];
  for (const f of feats) {
    const g = f && f.geometry;
    if (!g) continue;
    if (g.type === 'Polygon') {
      for (const ring of g.coordinates) rings.push(ring);
    } else if (g.type === 'MultiPolygon') {
      for (const poly of g.coordinates) for (const ring of poly) rings.push(ring);
    }
  }
  _franceRegionRingsCache = rings;
  return rings;
}
